/**
 * 视频播放器 - vid/video-player.js
 * 功能：封面提取、音量控制修复、全屏修复
 * 用法：
 *   VideoPlayer.initAll()  // 初始化页面所有 .video-player-container
 *   VideoPlayer.init(container)  // 初始化指定容器
 */
(function(global) {
    'use strict';

    function initVideoPlayer(container, options) {
        options = Object.assign({
            poster: '',
            autoplay: false,
            muted: false
        }, options || {});

        if (container.__videoPlayerInitialized) return;
        container.__videoPlayerInitialized = true;

        const video = container.querySelector('video');
        const poster = container.querySelector('.video-poster');
        const playBtn = container.querySelector('.play-button');
        const playPauseBtn = container.querySelector('.vp-play-pause');
        const progressBar = container.querySelector('.vp-progress-bar');
        const progressFill = container.querySelector('.vp-progress-fill');
        const progressHandle = container.querySelector('.vp-progress-handle');
        const timeDisplay = container.querySelector('.vp-time-display');
        const volumeBtn = container.querySelector('.vp-volume-btn');
        const volumeSlider = container.querySelector('.vp-volume-slider');
        const volumeFill = container.querySelector('.vp-volume-fill');
        const fullscreenBtn = container.querySelector('.vp-fullscreen-btn');

        if (!video) { console.error('Video element not found'); return; }

        // 设置视频源
        const src = container.dataset.src || '';
        if (src && !video.src) {
            video.src = src;
            video.load();
        }

        // 封面
        if (poster && options.poster) {
            poster.style.backgroundImage = `url(${options.poster})`;
            poster.style.backgroundSize = 'cover';
            poster.style.backgroundPosition = 'center';
        }

        let isPlaying = false;
        let isDraggingProgress = false;
        let isDraggingVolume = false;
        let isMuted = false;
        let lastVolume = 0.7;

        function formatTime(s) {
            if (isNaN(s) || s === Infinity) return '00:00';
            const m = Math.floor(s / 60);
            const sec = Math.floor(s % 60);
            return String(m).padStart(2,'0') + ':' + String(sec).padStart(2,'0');
        }

        // 播放/暂停
        function togglePlay(e) {
            if (e) e.stopPropagation();
            if (video.paused) {
                var p = video.play();
                if (p !== undefined) {
                    p.catch(function(err) {
                        // AbortError 由用户主动暂停引起，静默忽略
                        if (err.name === 'AbortError') return;
                        console.error('[VID-PLAY] Play failed:', err);
                    });
                }
                container.classList.add('playing');
                if (playPauseBtn) playPauseBtn.innerHTML = '<i class="fas fa-pause"></i>';
                if (playBtn) playBtn.style.display = 'none';
            } else {
                video.pause();
                container.classList.remove('playing');
                if (playPauseBtn) playPauseBtn.innerHTML = '<i class="fas fa-play"></i>';
                if (playBtn) playBtn.style.display = 'flex';
            }
        }

        if (playBtn) playBtn.addEventListener('click', togglePlay);
        if (playPauseBtn) playPauseBtn.addEventListener('click', togglePlay);
        video.addEventListener('click', function(e) {
            if (e.target === video) togglePlay(e);
        });

        // 进度更新
        video.addEventListener('timeupdate', function() {
            if (!isDraggingProgress && progressFill && progressHandle && video.duration) {
                const pct = (video.currentTime / video.duration) * 100;
                progressFill.style.width = pct + '%';
                progressHandle.style.left = pct + '%';
            }
            if (timeDisplay) {
                timeDisplay.textContent = formatTime(video.currentTime) + ' / ' + formatTime(video.duration || 0);
            }
        });

        // 进度条点击
        function handleProgressClick(e) {
            if (!progressBar || !video.duration) return;
            const rect = progressBar.getBoundingClientRect();
            const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
            video.currentTime = pct * video.duration;
        }
        if (progressBar) {
            progressBar.addEventListener('click', handleProgressClick);
        }

        // 进度条拖动
        if (progressHandle) {
            progressHandle.addEventListener('mousedown', function(e) {
                isDraggingProgress = true;
                e.preventDefault();
                document.body.style.userSelect = 'none';
            });
        }
        document.addEventListener('mousemove', function(e) {
            if (!isDraggingProgress || !progressBar || !video.duration) return;
            const rect = progressBar.getBoundingClientRect();
            const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
            progressFill.style.width = (pct * 100) + '%';
            progressHandle.style.left = (pct * 100) + '%';
            video.currentTime = pct * video.duration;
        });
        document.addEventListener('mouseup', function() {
            if (isDraggingProgress) {
                isDraggingProgress = false;
                document.body.style.userSelect = '';
            }
        });

        // 音量
        if (volumeBtn) {
            volumeBtn.addEventListener('click', function() {
                if (isMuted) {
                    video.volume = lastVolume;
                    if (volumeFill) volumeFill.style.width = (lastVolume * 100) + '%';
                    volumeBtn.innerHTML = '<i class="fas fa-volume-up"></i>';
                    isMuted = false;
                } else {
                    lastVolume = video.volume || 0.7;
                    video.volume = 0;
                    if (volumeFill) volumeFill.style.width = '0%';
                    volumeBtn.innerHTML = '<i class="fas fa-volume-mute"></i>';
                    isMuted = true;
                }
            });
        }
        if (volumeSlider) {
            volumeSlider.addEventListener('click', function(e) {
                const rect = volumeSlider.getBoundingClientRect();
                const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
                video.volume = pct;
                if (volumeFill) volumeFill.style.width = (pct * 100) + '%';
                isMuted = pct === 0;
                if (volumeBtn) {
                    volumeBtn.innerHTML = isMuted ? '<i class="fas fa-volume-mute"></i>' : '<i class="fas fa-volume-up"></i>';
                }
            });
        }

        // 全屏
        if (fullscreenBtn) {
            fullscreenBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                if (document.fullscreenElement) {
                    document.exitFullscreen();
                } else {
                    container.requestFullscreen();
                }
            });
        }

        // 视频结束
        video.addEventListener('ended', function() {
            container.classList.remove('playing');
            if (playPauseBtn) playPauseBtn.innerHTML = '<i class="fas fa-play"></i>';
            if (playBtn) playBtn.style.display = 'flex';
        });

        // 初始化音量
        video.volume = 0.7;
        if (volumeFill) volumeFill.style.width = '70%';

        // 从视频提取封面
        if (video.readyState >= 1) {
            try {
                if (poster) {
                    poster.style.backgroundImage = '';
                    poster.style.display = 'flex';
                }
            } catch(e) {}
        }

        // ==== 网络状态监听、断网提示与自动恢复 ====
        (function() {
            var retryCount = 0;
            var maxRetries = 3;
            var baseDelay = 1000;
            var maxDelay = 30000;
            var retryTimer = null;
            var isDisconnected = false;

            var netOverlay = container.querySelector('.vp-network-disconnected');
            if (!netOverlay) {
                netOverlay = document.createElement('div');
                netOverlay.className = 'vp-network-disconnected';
                netOverlay.innerHTML = '<i class="fas fa-wifi-slash"></i> 网络已断开，请检查连接';
                container.appendChild(netOverlay);
            }

            function showDisconnected() {
                isDisconnected = true;
                netOverlay.style.display = 'flex';
                video.pause();
            }

            function hideDisconnected() {
                isDisconnected = false;
                netOverlay.style.display = 'none';
                retryCount = 0;
            }

            window.addEventListener('online', function() {
                if (isDisconnected) {
                    console.log('[VID-NET] 网络已恢复，重新加载视频');
                    hideDisconnected();
                    video.load();
                    video.play().catch(function(){});
                }
            });

            window.addEventListener('offline', function() {
                if (!navigator.onLine) {
                    showDisconnected();
                }
            });

            video.addEventListener('error', function() {
                if (!navigator.onLine) {
                    showDisconnected();
                    return;
                }
                var mediaError = video.error;
                var isNetworkError = mediaError && (
                    mediaError.code === MediaError.MEDIA_ERR_NETWORK ||
                    (mediaError.message && mediaError.message.indexOf('Network') >= 0) ||
                    (mediaError.message && mediaError.message.indexOf('ERR_INTERNET_DISCONNECTED') >= 0)
                );
                if (isNetworkError) {
                    if (retryCount < maxRetries) {
                        var delay = Math.min(baseDelay * Math.pow(2, retryCount), maxDelay);
                        retryCount++;
                        console.log('[VID-NET] 网络错误，第 ' + retryCount + '/' + maxRetries + ' 次重试，等待 ' + delay + 'ms');
                        clearTimeout(retryTimer);
                        retryTimer = setTimeout(function() { video.load(); }, delay);
                    } else {
                        console.error('[VID-NET] 重试次数已达上限');
                        retryCount = 0;
                        var evt = new CustomEvent('playererror', {
                            detail: { type: 'network', message: '视频加载失败，请稍后重试' }
                        });
                        container.dispatchEvent(evt);
                    }
                }
            });
        })();
    }

    function initAll() {
        document.querySelectorAll('.video-player-container').forEach(function(container) {
            initVideoPlayer(container);
        });
    }

    // 自动初始化
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        setTimeout(initAll, 0);
    }

    global.VideoPlayer = {
        init: initVideoPlayer,
        initAll: initAll
    };

})(window);

/* 自定义视频播放器样式 - video-player.css */
:root {
    --vp-pink: #FB7299;
    --vp-blue: #00A1D6;
}

.video-player-container {
    position: relative;
    width: 100%;
    max-width: 800px;
    margin: 0 auto;
    border-radius: 16px;
    overflow: hidden;
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
    font-family: 'MaokenAssortedSans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.video-player-container video {
    width: 100%;
    height: auto;
    display: block;
    border-radius: 16px;
}

/* 海报层 */
.video-poster {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    cursor: pointer;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #1a1a2e;
}

.video-poster img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 16px;
}

.video-poster.hidden {
    display: none;
}

/* 播放按钮 */
.play-button {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 70px;
    height: 70px;
    background: linear-gradient(135deg, var(--vp-pink), var(--vp-blue));
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 30px rgba(251, 114, 153, 0.5);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    z-index: 3;
}

.play-button:hover {
    transform: translate(-50%, -50%) scale(1.1);
    box-shadow: 0 12px 40px rgba(251, 114, 153, 0.6);
}

.play-button i {
    color: white;
    font-size: 1.8rem;
    margin-left: 4px;
}

/* 控制栏 */
.video-controls {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
    padding: 40px 15px 15px;
    display: flex;
    align-items: center;
    gap: 10px;
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: 4;
}

.video-player-container:hover .video-controls,
.video-player-container.playing .video-controls,
.video-player-container.controls-visible .video-controls {
    opacity: 1;
}

/* 控制按钮 */
.vp-control-btn {
    background: none;
    border: none;
    color: white;
    font-size: 1rem;
    cursor: pointer;
    padding: 8px;
    border-radius: 6px;
    transition: background 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 36px;
    height: 36px;
}

.vp-control-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

/* 进度条 */
.vp-progress-container {
    flex: 1;
    height: 24px;
    display: flex;
    align-items: center;
    cursor: pointer;
    padding: 8px 0;
}

.vp-progress-bar {
    width: 100%;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    position: relative;
    overflow: visible;
}

.vp-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--vp-pink), var(--vp-blue));
    border-radius: 3px;
    width: 0%;
    transition: width 0.1s linear;
    position: relative;
}

.vp-progress-handle {
    position: absolute;
    top: 50%;
    left: 0%;
    transform: translate(-50%, -50%);
    width: 14px;
    height: 14px;
    background: white;
    border-radius: 50%;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    opacity: 0;
    transition: opacity 0.2s;
}

.vp-progress-container:hover .vp-progress-handle {
    opacity: 1;
}

/* 时间显示 */
.vp-time-display {
    color: white;
    font-size: 0.8rem;
    font-family: 'MaokenAssortedSans', 'Monaco', 'Menlo', monospace;
    min-width: 90px;
    text-align: center;
    white-space: nowrap;
}

/* 音量控制 */
.vp-volume-container {
    display: flex;
    align-items: center;
    gap: 6px;
}

.vp-volume-slider {
    width: 70px;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    cursor: pointer;
    position: relative;
}

.vp-volume-fill {
    height: 100%;
    background: white;
    border-radius: 3px;
    width: 70%;
}

/* 加载指示器 */
.vp-loading {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 50px;
    height: 50px;
    border: 4px solid rgba(255,255,255,0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: vp-spin 0.8s linear infinite;
    z-index: 5;
    display: none;
}

.video-player-container.loading .vp-loading {
    display: block;
}

/* 全屏样式 */
.video-player-container:fullscreen,
.video-player-container:-webkit-full-screen {
    border-radius: 0;
    max-width: 100%;
}

.video-player-container:fullscreen video,
.video-player-container:-webkit-full-screen video {
    border-radius: 0;
}

/* 键盘提示 */
.vp-keyboard-hint {
    position: absolute;
    bottom: 70px;
    right: 15px;
    background: rgba(0,0,0,0.7);
    color: white;
    padding: 8px 12px;
    border-radius: 8px;
    font-size: 0.75rem;
    opacity: 0;
    transition: opacity 0.3s;
    z-index: 10;
    pointer-events: none;
}

.video-player-container:hover .vp-keyboard-hint {
    opacity: 1;
}

@keyframes vp-spin {
    to { transform: translate(-50%, -50%) rotate(360deg); }
}

/* 断网提示覆盖层 */
.vp-network-disconnected {
    display: none;
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.75);
    color: #fff;
    align-items: center;
    justify-content: center;
    z-index: 20;
    font-size: 1rem;
    flex-direction: column;
    gap: 10px;
    pointer-events: none;
}

.vp-network-disconnected i {
    font-size: 2.5rem;
    color: #f59e0b;
    margin-bottom: 4px;
}

/**
 * 自定义视频播放器 - video-player.js
 * 功能：
 * 1. 修复音量控制问题
 * 2. 自动从视频中提取封面
 * 3. 修复全屏功能
 *
 * 用法：
 * VideoPlayer.init(container) - 初始化指定容器内的播放器
 * VideoPlayer.initAll() - 初始化页面上所有 .video-player-container
 */
(function(global) {
    'use strict';

    /**
     * 初始化视频播放器
     * @param {HTMLElement} container - .video-player-container 元素
     * @param {Object} options - 可选参数
     */
    function initVideoPlayer(container, options) {
        options = Object.assign({
            poster: '',
            autoplay: false,
            muted: false
        }, options || {});

        // 防止重复初始化
        if (container.__videoPlayerInitialized) return;
        container.__videoPlayerInitialized = true;

        const video = container.querySelector('video');
        const poster = container.querySelector('.video-poster');
        const playBtn = container.querySelector('.play-button');
        const playPauseBtn = container.querySelector('.play-pause-btn');
        const progressBar = container.querySelector('.vp-progress-bar');
        const progressFill = container.querySelector('.vp-progress-fill');
        const progressHandle = container.querySelector('.vp-progress-handle');
        const timeDisplay = container.querySelector('.vp-time-display');
        const volumeBtn = container.querySelector('.vp-volume-btn');
        const volumeSlider = container.querySelector('.vp-volume-slider');
        const volumeFill = container.querySelector('.vp-volume-fill');
        const fullscreenBtn = container.querySelector('.vp-fullscreen-btn');

        if (!video) {
            console.error('Video element not found in container', container);
            return;
        }

        // 设置视频源
        const src = container.dataset.src || '';
        if (src && !video.src) {
            video.src = src;
            video.load(); // 强制浏览器加载视频
        }

        // 状态变量
        let isPlaying = false;
        let isDraggingProgress = false;
        let isDraggingVolume = false;
        let isMuted = false;
        let lastVolume = 0.7;
        let hideControlsTimer = null;

        // ===== 1. 从视频生成封面 =====
        function generateVideoPoster() {
            if (poster && poster.dataset.generated) return;
            if (!video.videoWidth) return;

            try {
                const canvas = document.createElement('canvas');
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                const ctx = canvas.getContext('2d');
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const dataUrl = canvas.toDataURL('image/jpeg', 0.8);

                let img = poster.querySelector('img');
                if (!img) {
                    img = document.createElement('img');
                    img.className = 'vp-poster-img';
                    poster.insertBefore(img, poster.firstChild);
                }
                img.src = dataUrl;
                img.alt = '视频封面';
                poster.dataset.generated = 'true';
            } catch (e) {
                console.warn('Failed to generate video poster:', e);
            }
        }

        // ===== 2. 播放/暂停 =====
        function togglePlay(e) {
            if (e) e.stopPropagation();

            console.log('[PLAY] togglePlay called, paused:', video.paused, 'readyState:', video.readyState);

            if (video.paused || video.ended) {
                const playPromise = video.play();
                if (playPromise !== undefined) {
                    playPromise.then(() => {
                        console.log('[PLAY] Play started successfully');
                        isPlaying = true;
                        container.classList.add('playing');
                        container.classList.add('controls-visible');
                        updatePlayPauseBtn();
                        if (poster) poster.classList.add('hidden');
                    }).catch(err => {
                        // AbortError 由用户主动暂停引起，静默忽略
                        if (err.name === 'AbortError') return;
                        console.error('[PLAY] Play failed:', err);
                    });
                }
            } else {
                video.pause();
                isPlaying = false;
                container.classList.remove('playing');
                updatePlayPauseBtn();
            }
        }

        function updatePlayPauseBtn() {
            if (!playPauseBtn) return;
            playPauseBtn.innerHTML = isPlaying
                ? '<i class="fas fa-pause"></i>'
                : '<i class="fas fa-play"></i>';
        }

        if (playBtn) playBtn.addEventListener('click', togglePlay);
        if (playPauseBtn) playPauseBtn.addEventListener('click', togglePlay);
        video.addEventListener('click', function(e) {
            if (!e.target.closest('.video-controls')) {
                togglePlay(e);
            }
        });

        // ===== 3. 进度条 =====
        function updateProgress() {
            if (!isDraggingProgress && video.duration && isFinite(video.duration)) {
                const percent = (video.currentTime / video.duration) * 100;
                if (progressFill) progressFill.style.width = percent + '%';
                if (progressHandle) progressHandle.style.left = percent + '%';
            }
        }

        function updateTimeDisplay() {
            if (!timeDisplay) return;
            const current = formatTime(video.currentTime);
            const duration = formatTime(video.duration);
            timeDisplay.textContent = current + ' / ' + duration;
        }

        function formatTime(seconds) {
            if (isNaN(seconds) || !isFinite(seconds) || seconds < 0) return '00:00';
            const mins = Math.floor(seconds / 60);
            const secs = Math.floor(seconds % 60);
            return String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
        }

        if (progressBar) {
            progressBar.addEventListener('click', function(e) {
                e.stopPropagation();
                if (!video.duration) return;
                const rect = progressBar.getBoundingClientRect();
                const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
                video.currentTime = percent * video.duration;
            });
        }

        // 进度条拖动
        function onProgressMouseDown(e) {
            if (e.target.closest('.vp-progress-handle') || e.target === progressBar || e.target === progressFill) {
                isDraggingProgress = true;
                document.body.style.userSelect = 'none';
                e.preventDefault();
                e.stopPropagation();
            }
        }

        if (progressBar) {
            progressBar.addEventListener('mousedown', onProgressMouseDown);
        }

        // 视频事件
        video.addEventListener('loadedmetadata', function() {
            updateTimeDisplay();
            generateVideoPoster();
        });

        video.addEventListener('timeupdate', function() {
            updateProgress();
            updateTimeDisplay();
        });

        video.addEventListener('play', function() {
            isPlaying = true;
            container.classList.add('playing');
            updatePlayPauseBtn();
        });

        video.addEventListener('pause', function() {
            isPlaying = false;
            container.classList.remove('playing');
            updatePlayPauseBtn();
        });

        video.addEventListener('ended', function() {
            isPlaying = false;
            container.classList.remove('playing');
            updatePlayPauseBtn();
            if (poster) {
                poster.classList.remove('hidden');
                container.classList.remove('controls-visible');
            }
        });

        // ===== 4. 音量控制 =====
        function updateVolumeDisplay() {
            const vol = isMuted ? 0 : video.volume;
            if (volumeFill) volumeFill.style.width = (vol * 100) + '%';
            if (!volumeBtn) return;
            if (isMuted || vol === 0) {
                volumeBtn.innerHTML = '<i class="fas fa-volume-mute"></i>';
            } else if (vol < 0.5) {
                volumeBtn.innerHTML = '<i class="fas fa-volume-down"></i>';
            } else {
                volumeBtn.innerHTML = '<i class="fas fa-volume-up"></i>';
            }
        }

        function setVolume(percent) {
            percent = Math.max(0, Math.min(1, percent));
            video.volume = percent;
            lastVolume = percent;
            isMuted = percent === 0;
            updateVolumeDisplay();
        }

        if (volumeBtn) {
            volumeBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                if (isMuted || video.volume === 0) {
                    video.volume = lastVolume || 0.7;
                    isMuted = false;
                } else {
                    lastVolume = video.volume;
                    video.volume = 0;
                    isMuted = true;
                }
                updateVolumeDisplay();
            });
        }

        if (volumeSlider) {
            volumeSlider.addEventListener('click', function(e) {
                e.stopPropagation();
                const rect = volumeSlider.getBoundingClientRect();
                const percent = (e.clientX - rect.left) / rect.width;
                setVolume(percent);
            });

            volumeSlider.addEventListener('mousedown', function(e) {
                isDraggingVolume = true;
                e.preventDefault();
                e.stopPropagation();
            });
        }

        // 全局鼠标事件
        const onMouseMove = function(e) {
            if (isDraggingProgress && progressBar) {
                const rect = progressBar.getBoundingClientRect();
                let percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
                video.currentTime = percent * video.duration;
            }
            if (isDraggingVolume && volumeSlider) {
                const rect = volumeSlider.getBoundingClientRect();
                const percent = (e.clientX - rect.left) / rect.width;
                setVolume(percent);
            }
        };

        const onMouseUp = function() {
            isDraggingProgress = false;
            isDraggingVolume = false;
            document.body.style.userSelect = '';
        };

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);

        // 初始化音量
        video.volume = lastVolume;
        updateVolumeDisplay();

        // ===== 5. 全屏功能 =====
        function toggleFullscreen(e) {
            if (e) e.stopPropagation();

            const fsEl = document.fullscreenElement
                || document.webkitFullscreenElement
                || document.mozFullScreenElement
                || document.msFullscreenElement;

            if (fsEl) {
                // 退出全屏
                if (document.exitFullscreen) {
                    document.exitFullscreen();
                } else if (document.webkitExitFullscreen) {
                    document.webkitExitFullscreen();
                } else if (document.mozCancelFullScreen) {
                    document.mozCancelFullScreen();
                } else if (document.msExitFullscreen) {
                    document.msExitFullscreen();
                }
            } else {
                // 进入全屏 - 优先使用 video 元素
                const target = video;
                if (target.requestFullscreen) {
                    target.requestFullscreen();
                } else if (target.webkitRequestFullscreen) {
                    target.webkitRequestFullscreen();
                } else if (target.mozRequestFullScreen) {
                    target.mozRequestFullScreen();
                } else if (target.msRequestFullscreen) {
                    target.msRequestFullscreen();
                } else {
                    // 降级：全屏容器
                    if (container.requestFullscreen) {
                        container.requestFullscreen();
                    }
                }
            }
        }

        if (fullscreenBtn) {
            fullscreenBtn.addEventListener('click', toggleFullscreen);
        }

        function updateFullscreenBtn() {
            const isFs = !!(
                document.fullscreenElement
                || document.webkitFullscreenElement
                || document.mozFullScreenElement
                || document.msFullscreenElement
            );
            if (fullscreenBtn) {
                fullscreenBtn.innerHTML = isFs
                    ? '<i class="fas fa-compress"></i>'
                    : '<i class="fas fa-expand"></i>';
            }
        }

        document.addEventListener('fullscreenchange', updateFullscreenBtn);
        document.addEventListener('webkitfullscreenchange', updateFullscreenBtn);
        document.addEventListener('mozfullscreenchange', updateFullscreenBtn);
        document.addEventListener('MSFullscreenChange', updateFullscreenBtn);

        // ===== 6. 键盘快捷键 =====
        container.addEventListener('keydown', function(e) {
            switch(e.key) {
                case ' ':
                case 'k':
                case 'K':
                    e.preventDefault();
                    togglePlay(e);
                    break;
                case 'ArrowLeft':
                    video.currentTime = Math.max(0, video.currentTime - 5);
                    break;
                case 'ArrowRight':
                    video.currentTime = Math.min(video.duration || Infinity, video.currentTime + 5);
                    break;
                case 'ArrowUp':
                    e.preventDefault();
                    setVolume(video.volume + 0.1);
                    break;
                case 'ArrowDown':
                    e.preventDefault();
                    setVolume(video.volume - 0.1);
                    break;
                case 'm':
                case 'M':
                    if (volumeBtn) volumeBtn.click();
                    break;
                case 'f':
                case 'F':
                    toggleFullscreen(e);
                    break;
            }
        });

        container.tabIndex = 0;

        // ===== 7. 显示/隐藏控制栏 =====
        container.addEventListener('mousemove', function() {
            container.classList.add('controls-visible');
            clearTimeout(hideControlsTimer);
            if (isPlaying) {
                hideControlsTimer = setTimeout(function() {
                    container.classList.remove('controls-visible');
                }, 3000);
            }
        });

        container.addEventListener('mouseleave', function() {
            if (isPlaying) {
                hideControlsTimer = setTimeout(function() {
                    container.classList.remove('controls-visible');
                }, 1000);
            }
        });

        // ===== 8. 双击全屏 =====
        video.addEventListener('dblclick', function(e) {
            e.preventDefault();
            toggleFullscreen(e);
        });

        // ===== 9. 网络状态监听、断网提示与自动恢复 =====
        var _retryCount = 0;
        var _maxRetries = 3;
        var _baseDelay = 1000;
        var _maxDelay = 30000;
        var _retryTimer = null;
        var _isDisconnected = false;

        // 创建断网提示覆盖层
        var _netOverlay = container.querySelector('.vp-network-disconnected');
        if (!_netOverlay) {
            _netOverlay = document.createElement('div');
            _netOverlay.className = 'vp-network-disconnected';
            _netOverlay.innerHTML = '<i class="fas fa-wifi-slash"></i> 网络已断开，请检查连接';
            container.appendChild(_netOverlay);
        }

        function _showDisconnected() {
            _isDisconnected = true;
            _netOverlay.style.display = 'flex';
            video.pause();
        }

        function _hideDisconnected() {
            _isDisconnected = false;
            _netOverlay.style.display = 'none';
            _retryCount = 0;
        }

        // 断网恢复监听
        window.addEventListener('online', function _onOnline() {
            if (_isDisconnected) {
                console.log('[NET] 网络已恢复，重新加载视频');
                _hideDisconnected();
                video.load();
                video.play().catch(function() {});
            }
        });

        window.addEventListener('offline', function _onOffline() {
            if (!navigator.onLine) {
                _showDisconnected();
            }
        });

        // 视频网络错误重试（指数退避）
        video.addEventListener('error', function _onVideoError() {
            if (!navigator.onLine) {
                _showDisconnected();
                return;
            }

            var mediaError = video.error;
            var isNetworkError = mediaError && (
                mediaError.code === MediaError.MEDIA_ERR_NETWORK ||
                (mediaError.message && mediaError.message.indexOf('Network') >= 0) ||
                (mediaError.message && mediaError.message.indexOf('ERR_INTERNET_DISCONNECTED') >= 0)
            );

            if (isNetworkError) {
                if (_retryCount < _maxRetries) {
                    var delay = Math.min(
                        _baseDelay * Math.pow(2, _retryCount),
                        _maxDelay
                    );
                    _retryCount++;
                    console.log('[NET] 网络错误，第 ' + _retryCount + '/' + _maxRetries + ' 次重试，等待 ' + delay + 'ms');
                    clearTimeout(_retryTimer);
                    _retryTimer = setTimeout(function() {
                        video.load();
                    }, delay);
                } else {
                    console.error('[NET] 重试次数已达上限，触发 error 事件');
                    _retryCount = 0;
                    var evt = new CustomEvent('playererror', {
                        detail: { type: 'network', message: '视频加载失败，请稍后重试' }
                    });
                    container.dispatchEvent(evt);
                }
            }
        });

        // ===== 10. 初始化 =====
        // 如果视频已经有src，尝试生成封面
        if (video.src || video.currentSrc) {
            if (video.readyState >= 1) {
                generateVideoPoster();
                updateTimeDisplay();
            } else {
                // 等待 metadata 加载
                video.addEventListener('loadedmetadata', function onMeta() {
                    updateTimeDisplay();
                    generateVideoPoster();
                    video.removeEventListener('loadedmetadata', onMeta);
                });
            }
        }
    }

    // ===== 公共 API =====
    global.VideoPlayer = {
        /**
         * 初始化指定容器内的播放器
         * @param {HTMLElement} container - .video-player-container 元素
         */
        init: function(container) {
            if (!container) {
                console.error('VideoPlayer.init: container is required');
                return;
            }
            initVideoPlayer(container);
        },

        /**
         * 初始化页面上所有 .video-player-container
         */
        initAll: function() {
            document.querySelectorAll('.video-player-container').forEach(function(container) {
                initVideoPlayer(container);
            });
        }
    };

})(window);
